targets.expr:
(
    (
        sum(http_server_request_duration_seconds_bucket{le="$target", http_response_status_code=~"^2..$", instance=~"$instance"})
        + (
            sum(http_server_request_duration_seconds_bucket{le="$tolerated", http_response_status_code=~"^2..$", instance=~"$instance"})
            - sum(http_server_request_duration_seconds_bucket{le="$target", http_response_status_code=~"^2..$", instance=~"$instance"})
        ) / 2
    ) / sum(http_server_request_duration_seconds_count{instance=~"$instance", http_response_status_code=~"^2..$"})
) * 100

(
    (
        sum(http_server_request_duration_seconds_bucket{le="$target", http_response_status_code=~"^2..$", instance=~"$instance"}) by (instance)
        + (
            sum(http_server_request_duration_seconds_bucket{le="$tolerated", http_response_status_code=~"^2..$", instance=~"$instance"}) by (instance)
            - sum(http_server_request_duration_seconds_bucket{le="$target", http_response_status_code=~"^2..$", instance=~"$instance"}) by (instance)
        ) / 2
    ) / sum(http_server_request_duration_seconds_count{instance=~"$instance", http_response_status_code=~"^2..$"}) by (instance)
) * 100
